CREATE TABLE qa_reports (id TEXT PRIMARY KEY NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,manifest_id TEXT NOT NULL,manifest_hash TEXT NOT NULL,render_id TEXT,kind TEXT NOT NULL CHECK(kind IN('PRE_RENDER','FINAL')),version_no INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','BLOCKED','APPROVED')),revision INTEGER NOT NULL DEFAULT 1,findings_json TEXT NOT NULL CHECK(json_valid(findings_json)),created_at TEXT NOT NULL,reviewed_at TEXT,reviewed_by TEXT REFERENCES user(id),mutation_token TEXT,UNIQUE(project_id,version_no),FOREIGN KEY(manifest_id,project_id) REFERENCES render_manifests(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(render_id,project_id) REFERENCES renders(id,project_id) ON DELETE RESTRICT);
